function portalPage(){if(LIVE)return selfServicePage();return '<div class="portal-grid"><div class="portal-intro"><span class="eyebrow">YOUR WORK. YOUR SPACE.</span><h1>'+lawText('كل ما يخص شغلك.\nبين إيديك.','Your work.\nYour own space.')+'</h1><p>'+lawText('إجازاتك، كشف مرتبك، طلباتك ورحلة انضمامك. بوابة واحدة تبدأ منها يومك.','Your leave, payslips, requests and onboarding. One portal to start your day.')+'</p><div class="portal-features"><span>☷ '+lawText('طلب إجازة وتتبع الموافقات','Request leave and track approvals')+'</span><span>▣ '+lawText('كشوف المرتب الشهرية','Monthly payslips')+'</span><span>◇ '+lawText('سياسات الشركة ورحلة انضمامك','Company policies and onboarding')+'</span></div><div class="portal-eye"><svg viewBox="0 0 300 130"><path d="M10 65Q150 -40 290 65Q150 170 10 65Z" fill="none" stroke="#c8a252" stroke-width="2"/><circle cx="150" cy="65" r="42" fill="#c8a252"/><circle cx="150" cy="65" r="18" fill="#0b1f4a"/><circle cx="137" cy="49" r="8" fill="white"/></svg></div></div><div class="card portal-login"><span class="eyebrow">EMPLOYEE PORTAL</span><h2>'+lawText('أهلًا بيك من جديد.','Welcome back.')+'</h2><p>'+lawText('ادخل بيانات حسابك التجريبي.','Sign in with your demo account.')+'</p><form id="portalLogin" style="margin-top:25px"><div class="field"><label for="login-user">'+lawText('اسم المستخدم / البريد','Username / email')+'</label><input id="login-user" name="username" type="email" autocomplete="username" placeholder="employee1@example.com" required></div><div class="field"><label for="login-pass">'+lawText('كلمة المرور','Password')+'</label><input id="login-pass" name="password" type="password" autocomplete="current-password" required></div><button class="btn primary" type="submit" style="width:100%">'+lawText('تسجيل الدخول','Sign in')+'</button></form><div class="form-actions">'+btn(lawText('املأ حساب العرض','Fill demo account'),'demoCredentials','','small')+'</div><div class="notice blue" style="margin-top:22px">'+lawText('تسجيل دخول تجريبي فقط. المستخدم: employee1@example.com وكلمة المرور: welcome123. لا تستخدم كلمة مرورك الحقيقية. التشغيل الفعلي يستخدم دخول Google Workspace وصلاحيات الخادم.','Demo login only: employee1@example.com / welcome123. Do not use a real password. Live operation uses Google Workspace sign-in and server-side permissions.')+'</div>'+btn(lawText('رجوع لمساحة الإدارة','Back to admin demo'),'nav','dashboard','ghost')+'</div></div>';}
function selfServicePage(){const e=person(employeeId)||state.employees[0];if(!e)return heading(lawText('بوابة الموظف','Employee portal'),lawText('اربط بريد الموظف بملفه لتظهر بياناته هنا.','Link your employee email to a profile to display your data.'));const requests=state.leaves.filter(l=>l.employeeId===e.id),runs=state.payroll.filter(r=>r.rows.some(x=>x.employeeId===e.id));return heading(lawText('أهلًا '+e.name.split(' ')[0]+'. ده مكانك.','Hi '+e.name.split(' ')[0]+'. This is your space.'),lawText('طلباتك وبياناتك أنت، في مكان واحد.','Your own requests and records, in one place.'),btn(lawText('＋ طلب جديد','＋ New request'),'requestPicker','','primary')+(employeeSession&&!LIVE?btn(lawText('خروج من حساب العرض','Exit demo account'),'logoutDemo','','') :''),'EMPLOYEE SELF SERVICE')+'<div class="kpis">'+kpi(lawText('رصيد إجازاتك','Your leave balance'),e.leaveBalance-e.usedLeave,lawText('أيام سنوية متبقية','Annual days remaining'),'☷',true)+kpi(lawText('راتبك الأساسي','Your basic salary'),fmt(e.salary),state.settings.currency+' • '+lawText('قبل البدلات والخصومات','Before allowances and deductions'),'▣')+kpi(lawText('طلباتك المعلقة','Your pending requests'),allRequests().filter(l=>l.employeeId===e.id&&l.status==='pending').length,lawText('تابعها من مركز الطلبات','Track them in the request centre'),'◷')+kpi(lawText('رحلة انضمامك','Your onboarding'),Math.round(e.onboarding.length/state.policies.length*100)+'%',lawText('قراءة وفهم وإقرار السياسات','Read, understand and acknowledge policies'),'◇')+'</div><div class="grid">'+card(lawText('طلباتك وموافقاتها','Your requests & approvals'),lawText('ترى طلباتك فقط داخل بوابة الموظف','Only your requests appear in your portal'),btn(lawText('عرض كل طلباتي','View all my requests'),'allMyRequests','','small')+table([lawText('النوع','Type'),lawText('الفترة','Dates'),lawText('الأيام','Days'),lawText('الحالة','Status'),lawText('التفاصيل','Details')],requests.map(l=>'<tr><td>'+esc(l.type)+'</td><td class="mono">'+l.from+' → '+l.to+'</td><td>'+l.days+'</td><td>'+badge(l.status)+'</td><td>'+btn(lawText('متابعة','Track'),'leave',l.id,'small')+'</td></tr>')))+card(lawText('ملفك الوظيفي','Your employee profile'),esc(e.job)+' • '+esc(e.department),'<div class="person"><span class="avatar large">'+initials(e.name)+'</span><div><h3>'+esc(e.name)+'</h3><p class="mono">'+esc(e.email)+'</p></div></div><div class="statline">'+lawText('تاريخ الانضمام: ','Start date: ')+e.joinDate+'</div><div class="statline">'+lawText('رقم الموظف: ','Employee ID: ')+e.id+'</div><div class="form-actions">'+btn(lawText('سياسات الشركة ورحلتي','My onboarding & policies'),'nav','onboarding','small')+'</div>')+'</div>'+card(lawText('كشوف مرتبك','Your payslips'),lawText('افتح كشفك الشهري واحفظه PDF','Open your monthly payslip and save it as PDF'),runs.length?table([lawText('الشهر','Month'),lawText('الصافي','Net'),lawText('الحالة','Status'),''],runs.filter(r=>r.status!=='draft').map(r=>{const row=r.rows.find(x=>x.employeeId===e.id);return '<tr><td>'+r.month+'</td><td class="mono">'+money(row.net)+'</td><td>'+badge(r.status)+'</td><td>'+btn(lawText('افتح كشف مرتبك','Open payslip'),'myPayslip',r.month,'small primary')+'</td></tr>';})):'<div class="empty">'+lawText('لم تصدر كشوف مرتب بعد. في العرض: جهز شهرًا واعتمده من مساحة الإدارة أولًا.','No payslips issued yet. In the demo, prepare and approve a month from the admin workspace first.')+'</div>');}
